- `cartesianChart1` 是否已正确初始化并添加到 UI。
- LiveCharts 版本是否匹配（推荐使用最新版）。

是的，您完全理解正确！**要同时添加 3SD 和 2SD 两条分隔线，只需要创建两个独立的 `Section` 对象，然后将它们都添加到 Y 轴的 `Sections` 集合中**。这是 LiveCharts 中添加多条参考线的标准做法。

### 完整实现代码（添加 3SD 和 2SD 两条线）

```csharp
/// <summary>
/// 添加 3SD 和 2SD 计算分隔线
/// </summary>
public void AddDataIndicatorLines()
{
    // 确保 Y 轴已初始化（重要！）
    if (cartesianChart1.AxisY == null || cartesianChart1.AxisY.Count == 0)
    {
        cartesianChart1.AxisY.Add(new Axis());
    }
    var yAxis = cartesianChart1.AxisY[0];

    // ===== 创建 3SD 分隔线 =====
    var section3SD = new Section
    {
        Value = _QCDataLine.line3SD,  // 确保这是 3SD 的值（注意变量名！）
        Stroke = Brushes.Red,         // 红色
        StrokeThickness = 2,
        Fill = Brushes.Transparent,
        Label = "3SD",                // 标签文字
        LabelPosition = SectionLabelPosition.Start, // 标签位置（左侧）
        // 可选：设置虚线样式（更醒目）
        StrokeDashArray = new DoubleCollection { 4, 2 } 
    };

    // ===== 创建 2SD 分隔线 =====
    var section2SD = new Section
    {
        Value = _QCDataLine.line2SD,  // 确保这是 2SD 的值
        Stroke = Brushes.Blue,        // 蓝色（与 3SD 区分）
        StrokeThickness = 1.5,
        Fill = Brushes.Transparent,
        Label = "2SD",
        LabelPosition = SectionLabelPosition.Start,
        // 可选：不同虚线样式
        StrokeDashArray = new DoubleCollection { 2, 2 } 
    };

    // ===== 将两条线都添加到 Y 轴 =====
    yAxis.Sections.Add(section3SD);
    yAxis.Sections.Add(section2SD);

    // 强制刷新图表（确保立即显示）
    cartesianChart1.Update();
}
```

