## 2. Pytest suite for the Python implementation  

Save the algorithm from the previous answer in a module, e.g. `smallest_unique.py`, and place the tests in `test_smallest_unique.py`.

### `smallest_unique.py`

```python
# smallest_unique.py
from collections import defaultdict
from typing import Dict

def smallest_unique_substring(s: str) -> str:
    """Return the lexicographically smallest substring that contains every
    distinct character of `s` exactly once, or '' if none exists."""
    distinct = set(s)
    k = len(distinct)

    if k == 0 or k > len(s):
        return ""

    freq: Dict[str, int] = defaultdict(int)
    good = 0                     # #characters with count == 1 in the window

    # initialise first window
    for i in range(k):
        c = s[i]
        freq[c] += 1
        if freq[c] == 1:
            good += 1
        elif freq[c] == 2:
            good -= 1

    best = s[:k] if good == k else None

    # slide the window
    n = len(s)
    for left in range(1, n - k + 1):
        out_char = s[left - 1]
        freq[out_char] -= 1
        if freq[out_char] == 1:
            good += 1          # 2 → 1
        elif freq[out_char] == 0:
            good -= 1          # 1 → 0

        in_char = s[left + k - 1]
        freq[in_char] += 1
        if freq[in_char] == 1:
            good += 1          # new single occurrence
        elif freq[in_char] == 2:
            good -= 1          # duplicate created

        if good == k:
            cand = s[left:left + k]
            if best is None or cand < best:
                best = cand

    return best if best is not None else ""
```

