    # distinct = {å, ß, ç}
    s = "åßçå"
    # windows of length 3:
    #   "åßç"  -> valid, lexicographically smallest
    #   "ßçå"  -> also valid but larger
    assert smallest_unique_substring(s) == "åßç"


