def test_random_small():
    import random, string
    for _ in range(200):
        # generate a short random string (len 1‑8) from lowercase letters
        s = ''.join(random.choice(string.ascii_lowercase) for _ in range(random.randint(1, 8)))
        # brute‑force solution for verification
        distinct = set(s)
        k = len(distinct)
        best = None
        for i in range(len(s) - k + 1):
            sub = s[i:i+k]
            if set(sub) == distinct and len(set(sub)) == k:  # each appears once
                if best is None or sub < best:
                    best = sub
        expected = best if best is not None else ""
        assert smallest_unique_substring(s) == expected
