No extra CSS is included, so the page stays clean and functional. Feel free to tweak the wording or add a little styling later if you like!

**JavaScript – self‑contained snippet**  
*(copy‑paste this into a `<script>` tag that runs after the `<canvas id="c">` element has been added to the page)*  

```js
/* -------------------------------------------------------------
   Visual‑matrix snap‑to‑grid / snap‑to‑wireframe helper
   ------------------------------------------------------------- */

/* ---- 1️⃣  Canvas & offset handling --------------------------- */
// The canvas we draw on – change the id if yours is different.
const canvas = document.getElementById('c');
const ctx    = canvas.getContext('2d');

/*  canvasOffsets replaces the missing global that caused the
    “ReferenceError: canvasOffsets is not defined”.  It stores the
    left‑top offset of the canvas relative to the page so mouse
    coordinates can be translated into canvas coordinates.               */
let canvasOffsets = canvas.getBoundingClientRect();

/* Keep the offsets up‑to‑date if the page is scrolled or the
   canvas is moved/resized. */
window.addEventListener('resize', () => canvasOffsets = canvas.getBoundingClientRect());
window.addEventListener('scroll', () => canvasOffsets = canvas.getBoundingClientRect());

/* Helper – mouse position in canvas coordinates */
function mousePos(evt) {
    return {
        x: evt.clientX - canvasOffsets.left,
        y: evt.clientY - canvasOffsets.top
    };
}

/* -------------------------------------------------------------
   2️⃣  Grid definition & snapping helpers
   ------------------------------------------------------------- */
const GRID_SIZE = 40;               // distance between grid lines (px)

/* Snap a point to the nearest grid intersection */
function snapToGrid(pt) {
    return {
        x: Math.round(pt.x / GRID_SIZE) * GRID_SIZE,
        y: Math.round(pt.y / GRID_SIZE) * GRID_SIZE
    };
}

/* Wire‑frame data – replace with your own vertex list.
   For the demo we use a simple cube centred at (200,200). */
const wireVertices = [
    {x:100, y:100}, {x:300, y:100},
    {x:300, y:300}, {x:100, y:300},
    {x:150, y:150}, {x:250, y:150},
    {x:250, y:250}, {x:150, y:250}
];

/* Find the vertex that is closest to a point (within a tolerance). */
function snapToWireframe(pt, tolerance = 15) {
    let best = null, bestDist = Infinity;
    for (const v of wireVertices) {
        const dx = v.x - pt.x, dy = v.y - pt.y;
        const d  = Math.hypot(dx, dy);
        if (d < bestDist && d <= tolerance) {
            bestDist = d;
            best = v;
        }
    }
    // If a vertex is close enough return it, otherwise fall back to grid.
    return best ? {x: best.x, y: best.y, snappedTo: 'wireframe'} : null;
}

/* -------------------------------------------------------------
   3️⃣  State & line storage
   ------------------------------------------------------------- */
let isDrawing   = false;          // true after first click, waiting for second
let startPoint  = null;           // {x, y, snappedTo}
const lines      = [];            // array of {p1, p2}

/* -------------------------------------------------------------
   4️⃣  Mouse event handlers – the core of the snapping logic
   ------------------------------------------------------------- */
canvas.addEventListener('mousedown', evt => {
    const raw   = mousePos(evt);
    const grid  = snapToGrid(raw);
    const wire  = snapToWireframe(raw);

    // Choose the “stronger” snap – wireframe takes precedence if within tolerance.
    const pt = wire ? {...wire, snappedTo: 'wireframe'} : {...grid, snappedTo: 'grid'};

    if (!isDrawing) {
        // First click → store start point
        startPoint = pt;
        isDrawing  = true;
    } else {
        // Second click → store end point, create line, reset state
        const endPoint = pt;
        lines.push({p1: startPoint, p2: endPoint});
        isDrawing  = false;
        startPoint = null;
        redraw();                     // draw the new line (grid stays static)
    }
});

canvas.addEventListener('mousemove', evt => {
    // Optional: show a preview line while the user is dragging.
    // This does **not** modify the permanent drawing.
    if (!isDrawing) return;
    const raw   = mousePos(evt);
    const grid  = snapToGrid(raw);
    const wire  = snapToWireframe(raw);
    const curPt = wire ? {...wire, snappedTo: 'wireframe'} : {...grid, snappedTo: 'grid'};
    previewLine(startPoint, curPt);
});

/* -------------------------------------------------------------
   5️⃣  Drawing helpers – grid is drawn **once**; lines are added
        only on click.  No automatic grid redraw on mousemove.
   ------------------------------------------------------------- */
function drawGrid() {
    ctx.strokeStyle = '#e0e0e0';
    ctx.lineWidth   = 1;
    for (let x = 0; x <= canvas.width; x += GRID_SIZE) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, canvas.height);
        ctx.stroke();
    }
    for (let y = 0; y <= canvas.height; y += GRID_SIZE) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(canvas.width, y);
        ctx.stroke();
    }
}

/* Draw all stored lines */
function drawLines() {
    ctx.strokeStyle = '#000';
    ctx.lineWidth   = 2;
    for (const ln of lines) {
        ctx.beginPath();
        ctx.moveTo(ln.p1.x, ln.p1.y);
        ctx.lineTo(ln.p2.x, ln.p2.y);
        ctx.stroke();
    }
}

/* Full redraw – grid + permanent lines */
function redraw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawGrid();
    drawLines();
}

/* Preview line while dragging – does not affect stored lines */
function previewLine(p1, p2) {
    redraw();                       // clear previous preview
    ctx.strokeStyle = 'rgba(0,0,255,0.5)';
    ctx.lineWidth   = 1;
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    ctx.moveTo(p1.x, p1.y);
    ctx.lineTo(p2.x, p2.y);
    ctx.stroke();
    ctx.setLineDash([]);            // reset dash for later drawing
}

/* -------------------------------------------------------------
   6️⃣  Initialisation
   ------------------------------------------------------------- */
drawGrid();                         // draw static grid once at start
```

### What changed / why the error disappeared
* **`canvasOffsets` is now a real variable** – it stores the result of `canvas.getBoundingClientRect()` and is refreshed on `resize`/`scroll`.  
* All mouse‑coordinate calculations use `mousePos(evt)`, which subtracts those offsets, so the code no longer references an undefined global.  

### Behaviour achieved
1. **Snapping** – on each click the point is snapped either to the nearest grid intersection **or** (if within ~15 px) to the nearest wire‑frame vertex.  
2. **User‑driven drawing** – the grid is drawn once (`drawGrid()`) and never redrawn automatically; only clicks push a new line into `lines` and trigger `redraw()`.  
3. **Pure JavaScript** – the snippet contains only JavaScript; you can drop it into any page that already has a `<canvas id="c">` element of the desired size.  

Feel free to replace `wireVertices` with your actual 3‑D projection data and adjust `GRID_SIZE` or the tolerance value to suit your visual‑matrix tool. Happy snapping!

