    const config = getAuthConfig();
    const response = await axios.get('/words/random', config);
    dispatch(setWord(response.data));
  } catch (error) {
    console.error('Error fetching word:', error);
  }
};

export const fetchNouns = () => async (dispatch) => {
  try {
    const config = getAuthConfig();
    const [masculineResponse, feminineResponse] = await Promise.all([
      axios.get('/words/masculine', config),
      axios.get('/words/feminine', config),
    ]);
    dispatch(
      setNouns({
        masculine: masculineResponse.data,
        feminine: feminineResponse.data,
      })
    );
  } catch (error) {
    console.error('Error fetching nouns:', error);
  }
};

export const fetchTranslation = (word) => async (dispatch) => {
  try {
    const config = getAuthConfig();
    const response = await axios.get(`/words/example?word=${word}`, config);
    dispatch(setTranslation(response.data));
    return response.data;
  } catch (error) {
    console.error('Error fetching translation:', error);
  }
};

export const submitAnswer = (selected) => async (dispatch, getState) => {
  const wordObj = selectWord(getState());
  // Fixed destructuring - wordObj contains both word and gender
  const { word: wordString, gender } = wordObj;

  // Fixed gender comparison (uses 'm'/'f' from API)
  const isCorrect = selected === (gender === 'm' ? 'UN/LE' : 'UNE/LA');

  if (isCorrect) {
    dispatch(setCorrect());
    await dispatch(fetchTranslation(wordString));
  } else {
    dispatch(setWrong());

    // Get noun endings from state instead of undefined variables
    const nounList = selectNouns(getState());
    const endings = gender === 'm' 
      ? nounList.masculine 
      : nounList.feminine;

    let correctEnding = '';
    // Fixed loop using actual endings from state
    for (const ending of endings) {
      if (wordString.endsWith(ending)) {
        correctEnding = ending;
        break;
      }
    }

    if (!correctEnding) {
      correctEnding = wordString;
    }

    // Fixed article determination (uses 'm'/'f')
    const correctArticle = gender === 'm' ? 'LE' : 'LA';
    dispatch(
      setCorrectArticle({ 
        article: correctArticle, 
        ending: correctEnding 
      })
    );
  }

  // Fetch translation for current word (regardless of correctness)
  await dispatch(fetchTranslation(wordString));
  dispatch(nextWord());
};

export const nextWord = () => (dispatch) => {
  dispatch(fetchWord());
};

export default wordsSlice.reducer;
```

