## 7.  Full corrected UDF (copy‑paste ready)

```c
#include "udf.h"
#define _USE_MATH_DEFINES   /* only needed on Windows */
#include <math.h>

#define DEG2RAD (M_PI/180.0)

/* --------------------------------------------------------------
   Helper that returns the heat‑flux value for a given angle (deg)
   -------------------------------------------------------------- */
static real heat_flux (real ang_deg)
{
    if (ang_deg < 90.0)
        return -0.0795*ang_deg*ang_deg + 62.3493*ang_deg - 1.0790e4;

    else if (ang_deg < 180.0)
        return -0.0340*ang_deg*ang_deg - 5.5136*ang_deg + 1.1331e3;

    else if (ang_deg <= 220.0)
        return -1.0883*pow(ang_deg,3) + 365.4279*ang_deg*ang_deg
               - 3.9214e4*ang_deg + 1.3631e6;

    else if (ang_deg < 251.0)
        return 5.7906e4*sin((0.0269*ang_deg + 10.3998)*DEG2RAD)
             + 1.2234e4*sin((0.0692*ang_deg + 19.7715)*DEG2RAD);

    else if (ang_deg < 270.0)
        return 8.2149e4*sin((0.1467*ang_deg + 1.7814)*DEG2RAD)
             + 4.7973e4*sin((0.2161*ang_deg + 18.1853)*DEG2RAD);

    else if (ang_deg < 286.0)
    {
        real a1 = (ang_deg - 194.8273)/3.2473;
        real a2 = (ang_deg - 7.2745e3)/1.2025e3;
        return 4.3734e3*exp(-a1*a1) + 4.2055e19*exp(-a2*a2);
    }

    else if (ang_deg <= 317.0)
        return 4.4359*ang_deg*ang_deg - 1.6072e3*ang_deg + 1.8613e5;

    else
        return 1.1431*pow(ang_deg,3) - 848.0460*ang_deg*ang_deg
               + 2.0802e5*ang_deg - 1.6842e7;
}

/* --------------------------------------------------------------
   UDF that assigns the heat‑flux profile on the selected wall
   -------------------------------------------------------------- */
DEFINE_PROFILE(angle_profile, t, i)
{
    real x[ND_ND];
    face_t f;

    begin_f_loop(f, t)
    {
        F_CENTROID(x, f, t);                     /* x[0]=X, x[1]=Y */
        real ang_rad = atan2(x[1], x[0]);        /* atan2(y,x) */
        real ang_deg = ang_rad * 180.0 / M_PI;   /* convert to deg */

        if (ang_deg < 0.0)                       /* wrap to [0,360) */
            ang_deg += 360.0;

        F_PROFILE(f, t, i) = heat_flux(ang_deg);
    }
    end_f_loop(f, t);
}
```

