### Java

```java
// FuelEfficiency.java
import java.util.Scanner;

public class FuelEfficiency {

    private static double calculateMpg(double miles, double gallons) {
        if (gallons <= 0) {
            throw new IllegalArgumentException("Gallons must be greater than zero.");
        }
        return miles / gallons;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        System.out.print("Enter the number of miles driven: ");
        while (!sc.hasNextDouble()) {
            System.out.print("Please enter a valid number: ");
            sc.next();
        }
        double miles = sc.nextDouble();

        System.out.print("Enter the number of gallons of gas used: ");
        while (!sc.hasNextDouble()) {
            System.out.print("Please enter a valid number: ");
            sc.next();
        }
        double gallons = sc.nextDouble();

        try {
            double mpg = calculateMpg(miles, gallons);
            System.out.printf("Fuel efficiency: %.2f miles per gallon (MPG)%n", mpg);
        } catch (IllegalArgumentException e) {
            System.err.println("Error: " + e.getMessage());
        }

        sc.close();
    }
}
```

