  children.forEach((child) => {
    const menu = {
      id: child.id,
      parentId: parentId,
      name: child.name,
      path: child.path,
      access: child.code,
      children: parseChildren(child.children, child.id),
    };
    if (child.microAppCode) {
      menu.element = <MicroAppElement NAME_2={child.microAppCode} path={child.microAppPath} />;
    }
    if (child.icon) {
      menu.icon = React.createElement(Icons[child.icon]);
    }
    menus.push(menu);
  });
  return menus;
};

let extraRoutes;

export function patchClientRoutes({ routes }) {
  if (extraRoutes) {
    for (let i = extraRoutes.length - 1; i >= 0; i--) {
      routes[1].routes.unshift(extraRoutes[i]);
    }
  }
}

export function render(oldRender) {
  fetch('/integration/menus/tree')
    .then((res) => {
      return res.json();
    })
    .then((result) => {
      let menus = new Array();
      if (result.ok) {
        result.data.forEach((element) => {
          let menu = {
            id: element.id,
            name: element.name,
            path: element.path,
            access: element.code,
            children: parseChildren(element.children, element.id),
          };
          if (element.microAppCode) {
            menu.element = (
              <MicroAppElement NAME_2={element.microAppCode} path={element.microAppPath} />
            );
          }
          if (element.icon) {
            menu.icon = React.createElement(Icons[element.icon]);
          }

          menus.push(menu);
        });
      }

      extraRoutes = menus;
      oldRender();
    });
}

要解决路由只在初始化时生效的问题，关键在于**确保动态路由数据在路由初始化前完成加载**。原代码中 `extraRoutes` 的赋值发生在 `render` 钩子中（路由已初始化后），导致动态路由无法被正确注入。以下是修改方案：

### 核心问题
1. **`patchClientRoutes` 执行时机过早**：在路由初始化时同步执行，但此时 `extraRoutes` 尚未通过异步请求获取
2. **`render` 钩子无法影响路由初始化**：`render` 在路由初始化后执行，无法修改已生成的路由配置

### 解决方案
1. **将动态路由获取移到 `patchClientRoutes` 中**：利用 Umi 支持异步 `patchClientRoutes` 的特性
2. **移除全局变量 `extraRoutes`**：避免异步状态管理问题
3. **确保路由数据加载完成后再初始化路由**

### 修改后的代码
```typescript
export const qiankun = fetch('/integration/micro-NAME_1')
  .then((res) => res.json())
  .then((result) => {
    if (result.ok) {
      const NAME_1: any[] = [];
      result.data.forEach((NAME_2) => {
        NAME_1.push({
          name: NAME_2.code,
          entry: '//' + NAME_2.url,
        });
      });
      return { apps: NAME_1 }; // 修正返回结构（qiankun 插件要求 apps 字段）
    }
    return { apps: [] }; // 确保始终返回有效结构
  });

export function useQiankunStateForSlave() {
  return { qiankun: true };
}

const parseChildren = (children: API.MenuTreeDTO[] | undefined, parentId: any) => {
  if (!children) return undefined;
  return children.map((child) => {
    const menu = {
      id: child.id,
      parentId,
      name: child.name,
      path: child.path,
      access: child.code,
      children: parseChildren(child.children, child.id),
    };
    if (child.microAppCode) {
      menu.element = <MicroAppElement NAME_2={child.microAppCode} path={child.microAppPath} />;
    }
    if (child.icon) {
      menu.icon = React.createElement(Icons[child.icon]);
    }
    return menu;
  });
};

// 修改点：将动态路由获取移到 patchClientRoutes 中并改为异步
export function patchClientRoutes({ routes }: { routes: any[] }) {
  return fetch('/integration/menus/tree')
    .then((res) => res.json())
    .then((result) => {
      if (result.ok && routes[1]?.routes) {
        const menus = result.data.map((element: any) => {
          const menu = {
            id: element.id,
            name: element.name,
            path: element.path,
            access: element.code,
            children: parseChildren(element.children, element.id),
          };
          if (element.microAppCode) {
            menu.element = (
              <MicroAppElement NAME_2={element.microAppCode} path={element.microAppPath} />
            );
          }
          if (element.icon) {
            menu.icon = React.createElement(Icons[element.icon]);
          }
          return menu;
        });

        // 逆序插入保持原始顺序
        for (let i = menus.length - 1; i >= 0; i--) {
          routes[1].routes.unshift(menus[i]);
        }
      }
    })
    .catch((err) => {
      console.error('Failed to load dynamic routes:', err);
    });
}

// 修改点：移除 render 中的路由加载逻辑
export function render(oldRender: () => void) {
  oldRender(); // 直接渲染，路由已通过 patchClientRoutes 注入
}
```

### 关键修改说明

1. **`patchClientRoutes` 改为异步函数**：
   - Umi 会等待返回的 Promise 完成后再进行路由初始化
   - 确保动态路由数据在路由生成前已加载完成
   - 通过 `.catch` 避免请求失败阻塞应用启动

2. **移除全局状态 `extraRoutes`**：
   - 消除异步状态管理问题
   - 直接在获取数据后立即 patch 路由

3. **修正 qiankun 配置结构**：
   - 显式返回 `{ apps: [...] }` 结构（符合 qiankun 插件要求）
   - 添加失败回退确保始终返回有效结构

4. **简化 `render` 钩子**：
   - 不再处理路由逻辑，仅保留渲染调用
   - 避免重复请求和状态冲突

### 为什么这样修改有效？

| 时机                | 原代码问题                          | 修改后方案                          |
|---------------------|-----------------------------------|-----------------------------------|
| **路由初始化前**     | `patchClientRoutes` 同步执行时 `extraRoutes` 未定义 | 异步等待路由数据加载完成后再 patch |
| **路由初始化中**     | 路由生成时缺少动态路由配置            | 路由生成时已包含完整动态路由         |
| **首次渲染时**       | `render` 中设置 `extraRoutes` 为时已晚 | 路由已完整，直接渲染即可            |

> **关键点**：Umi 的 `patchClientRoutes` 支持返回 Promise，这是官方推荐的动态路由加载方式。通过将异步请求移到此处，确保了路由系统在初始化时就能获取到完整的路由配置。

### 补充建议

1. **添加加载状态**（可选）：
   ```typescript
   export function render(oldRender: () => void) {
     const [loading, setLoading] = useState(true);

     fetch('/integration/menus/tree')
       .then(/*...*/)
       .finally(() => setLoading(false));

     return loading ? <PageLoading /> : oldRender();
   }
   ```
   但注意：**不要在此处获取路由数据**（路由已通过 `patchClientRoutes` 注入），仅用于展示加载状态

2. **错误处理增强**：
   ```typescript
   // 在 patchClientRoutes 中
   .catch((err) => {
     console.error('Route loading failed, using fallback routes:', err);
     // 可在此处注入默认路由防止白屏
   })
   ```

此方案确保：
- 所有路由（包括动态路由）在**首次渲染前**完成初始化
- 符合 Umi 路由生命周期规范
- 消除异步状态管理导致的路由丢失问题
- 保持与 qiankun 微前端架构的兼容性

Отличный вопрос! Правильное именование переменных — ключ к поддерживаемому и понятному коду.

В вашем случае переменная должна отражать, сколько **обычных** уровней было пройдено **с момента последнего** прохождения супер-уровня.

### Краткий и лучший вариант

Лучше всего использовать имя, которое описывает именно этот "счётчик".

**`normalLevelsSinceLastSuper`**

Это имя:
*   **Ёмкое:** Сразу понятно, что мы считаем (`normalLevels`).
*   **Точное:** Указывает на условие (`SinceLastSuper`).
*   **Легко читается:** Не требует расшифровки.

---

### Подробные варианты с объяснениями

Давайте рассмотрим два основных подхода к решению вашей задачи и соответствующие имена для них.

#### Подход 1: Счётчик (самый простой и рекомендуемый)

Вы храните переменную-счётчик, которую увеличиваете после каждого обычного уровня и сбрасываете в ноль после прохождения супер-уровня.

**Как это работает:**
1.  Игрок проходит супер-уровень. Вы делаете `normalLevelsSinceLastSuper = 0;`
2.  Игрок проходит обычный уровень. Вы делаете `normalLevelsSinceLastSuper++;`
3.  Проверяете условие разблокировки: `if (normalLevelsSinceLastSuper >= 5) { /* разблокировать кнопки */ }`

**Варианты названий для переменной-счётчика:**

*   **`normalLevelsSinceLastSuper`** (Лучший)
*   `levelsSinceSuperLevelCompletion`
*   `progressUntilNextSuper` (если нужно сыграть 5 уровней, то эта переменная будет считать от 0 до 5)
*   `superLevelLockCounter`

**Пример в коде:**
```csharp
public class LevelManager : MonoBehaviour
{
    // Сколько обычных уровней нужно пройти после супер-уровня
    private const int REQUIRED_LEVELS_AFTER_SUPER = 5; 

    // Наша переменная-счётчик
    private int normalLevelsSinceLastSuper = 0; 

    public void OnNormalLevelCompleted()
    {
        normalLevelsSinceLastSuper++;
        CheckSuperLevelUnlock();
        SaveProgress();
    }

    public void OnSuperLevelCompleted()
    {
        // Сбрасываем счётчик после прохождения супер-уровня
        normalLevelsSinceLastSuper = 0; 
        LockNextSuperLevel(); // Блокируем следующий
        SaveProgress();
    }

    private void CheckSuperLevelUnlock()
    {
        if (normalLevelsSinceLastSuper >= REQUIRED_LEVELS_AFTER_SUPER)
        {
            UnlockNextSuperLevel();
        }
    }
}
```

---

#### Подход 2: "Снимок" состояния

Вы храните общее количество пройденных обычных уровней на тот момент, когда был пройден супер-уровень. Чтобы проверить, можно ли разблокировать следующий супер-уровень, вы вычитаете это значение из текущего общего количества пройденных уровней.

**Как это работает:**
1.  Есть переменная `totalNormalLevelsCompleted` (общее число пройденных обычных уровней).
2.  Игрок проходит супер-уровень. Вы сохраняете: `totalNormalLevelsOnLastSuper = totalNormalLevelsCompleted;`
3.  Проверяете условие: `if (totalNormalLevelsCompleted - totalNormalLevelsOnLastSuper >= 5) { /* разблокировать */ }`

**Варианты названий для переменной-"снимка":**

*   **`totalLevelsOnLastSuperComplete`** (Очень точное)
*   `lastSuperLevelCompletedAt` (означает "супер-уровень был пройден на уровне N")
*   `normalLevelCountAtLastSuper`

**Пример в коде:**
```csharp
public class LevelManager : MonoBehaviour
{
    private const int REQUIRED_LEVELS_AFTER_SUPER = 5;

    // Общее количество пройденных обычных уровней за всё время
    private int totalNormalLevelsCompleted = 0; 

    // Наша переменная-"снимок"
    private int totalLevelsOnLastSuperComplete = 0;

    public void OnNormalLevelCompleted()
    {
        totalNormalLevelsCompleted++;
        CheckSuperLevelUnlock();
        SaveProgress();
    }

    public void OnSuperLevelCompleted()
    {
        // Сохраняем "снимок" общего прогресса
        totalLevelsOnLastSuperComplete = totalNormalLevelsCompleted; 
        LockNextSuperLevel();
        SaveProgress();
    }

    private void CheckSuperLevelUnlock()
    {
        int levelsCompletedSinceSuper = totalNormalLevelsCompleted - totalLevelsOnLastSuperComplete;
        if (levelsCompletedSinceSuper >= REQUIRED_LEVELS_AFTER_SUPER)
        {
            UnlockNextSuperLevel();
        }
    }
}
```

---

### Сравнение подходов и итоговая рекомендация

| Подход | Плюсы | Минусы |
|---|---|---|
| **1. Счётчик** | - Очень простая логика (инкремент и сброс).<br>- Легко читать и отлаживать.<br>- Не требует второй переменной для общего счёта. | - Состояние переменной меняется постоянно. Нужно не забыть её сбросить. |
| **2. Снимок** | - Более "стабильные" данные. Легко сохранять/загружать.<br>- Логика вычисления "разницы" может быть полезна в других местах (например, для статистики). | - Требует как минимум двух переменных (общий счёт и снимок).<br>- Логика проверки немного сложнее (нужно вычитание). |

**Итог:**

Для вашей задачи **Подход 1 (Счётчик) является более простым, интуитивным и рекомендуемым.**

Имя переменной **`normalLevelsSinceLastSuper`** идеально описывает её суть в рамках этого подхода. Оно сразу говорит программисту, что это счётчик, который обнуляется в определённый момент.

