### 🔔 **Sistema de Notificações (Desafio Principal)**

```dart
// Lógica para calcular próxima notificação
DateTime calcularProximoAlarme(Medicamento med) {
  DateTime agora = DateTime.now();

  if (med.frequencia == FrequenciaTipo.diario) {
    // Para medicamentos em horários fixos
    for (var horario in med.horarios) {
      DateTime horarioHoje = DateTime(
        agora.year, agora.month, agora.day, 
        horario.hora.hour, horario.hora.minute
      );

      if (horarioHoje.isAfter(agora)) {
        return horarioHoje;
      }
    }

    // Se todos passaram hoje, agendar para amanhã
    return DateTime(
      agora.year, agora.month, agora.day + 1,
      med.horarios.first.hora.hour, med.horarios.first.hora.minute
    );
  }

  // Para intervalos (ex: a cada 6h)
  return agora.add(Duration(hours: med.intervaloHoras!));
}
