    my $non_text = $sample =~ tr/\x00-\x08\x0B\x0C\x0E-\x1F\x7F-\xFF//;
    my $text_ratio = 1 - ($non_text / length($sample));

    # Special handling for UTF-16/32 (high null byte density)
    my $null_density = $sample =~ tr/\0// / length($sample);
    return 1 if $null_density > 0.3;

    # Threshold: 85%+ printable = text, otherwise binary
    return ($text_ratio < 0.85);
