if ($is_binary) {
    # BINARY MODE: Professional hex dump with semantic formatting
    say "\n<< BINARY FILE DETECTED >>";
    say "Displaying hex dump (offset: hex bytes  |  ASCII representation)\n";

    my $offset = 0;
    while (my $n = read($fh, my $chunk, $CHUNK_SIZE)) {
