```csharp
using System;
using System.Text;
using System.Collections.Generic;

class Program
{
    /// <summary>
    /// Atbash (mirror) substitution. Upper‑case ↔ Upper‑case, lower‑case ↔ lower‑case.
    /// Non‑letters are returned unchanged.
    /// </summary>
    static char Atbash(char c)
    {
        if (c >= 'A' && c <= 'Z')
            return (char)('Z' - (c - 'A'));
        if (c >= 'a' && c <= 'z')
            return (char)('z' - (c - 'a'));
        return c;
    }

    static void Main(string[] args)
    {
        // ---------- optional flag ----------
        bool skipEmpty = false;
        foreach (var a in args)
        {
            if (a == "-s" || a == "--skip-empty")
                skipEmpty = true;
        }

        // ---------- read number of lines ----------
        if (!int.TryParse(Console.ReadLine(), out int n))
            return; // malformed input

        long totalLetters   = 0; // only alphabetic characters
        long changedLetters = 0; // letters that changed after Atbash
        var outputLines = new List<string>(n);

        // ---------- process each line ----------
        for (int i = 0; i < n; i++)
        {
            string line = Console.ReadLine() ?? string.Empty;

            // If we are skipping empty lines, just ignore them completely
            if (skipEmpty && line.Length == 0)
                continue;

            var sb = new StringBuilder(line.Length);
            foreach (char ch in line)
            {
                char transformed = Atbash(ch);
                sb.Append(transformed);

                // Count only letters for the security decision
                if (char.IsLetter(ch))
                {
                    totalLetters++;
                    if (transformed != ch)
                        changedLetters++;
                }
            }
            outputLines.Add(sb.ToString());
        }

        // ---------- output translated lines ----------
        foreach (var outLine in outputLines)
            Console.WriteLine(outLine);

        // ---------- security decision ----------
        // If there are no letters at all we consider the message insecure.
        bool isSecure = totalLetters > 0 && (2 * changedLetters >= totalLetters);
        Console.WriteLine(isSecure ? "Secure" : "Insecure");
    }
}
```

