**2️⃣  Adding a `‑h / --help` usage message**

Only a few extra lines are needed – we check the arguments **before** we start reading the input.  
If a help flag is present we print a short description and exit.

```csharp
using System;
using System.Text;
using System.Collections.Generic;

class Program
{
    static char Atbash(char c)
    {
        if (c >= 'A' && c <= 'Z') return (char)('Z' - (c - 'A'));
        if (c >= 'a' && c <= 'z') return (char)('z' - (c - 'a'));
        return c;
    }

    static void Main(string[] args)
    {
        // ---------- help flag ----------
        foreach (var a in args)
        {
            if (a == "-h" || a == "--help")
            {
                PrintHelp();
                return;
            }
        }

        // ---------- optional skip‑empty flag ----------
        bool skipEmpty = false;
        foreach (var a in args)
            if (a == "-s" || a == "--skip-empty") skipEmpty = true;

        // ---------- read number of lines ----------
        if (!int.TryParse(Console.ReadLine(), out int n))
            return;                     // malformed input

        long totalLetters   = 0;
        long changedLetters = 0;
        var outputLines = new List<string>(n);

        // ---------- process each line ----------
        for (int i = 0; i < n; i++)
        {
            string line = Console.ReadLine() ?? string.Empty;

            // ignore empty lines when the flag is on
            if (skipEmpty && line.Length == 0) continue;

            var sb = new StringBuilder(line.Length);
            foreach (char ch in line)
            {
                char transformed = Atbash(ch);
                sb.Append(transformed);

                if (char.IsLetter(ch))
                {
                    totalLetters++;
                    if (transformed != ch) changedLetters++;
                }
            }
            outputLines.Add(sb.ToString());
        }

        // ---------- output ----------
        foreach (var outLine in outputLines) Console.WriteLine(outLine);

        // ---------- security decision (guard for “no letters”) ----------
        bool isSecure = totalLetters > 0 && (2 * changedLetters >= totalLetters);
        Console.WriteLine(isSecure ? "Secure" : "Insecure");
    }

    // -------------------------------------------------------------
    static void PrintHelp()
    {
        Console.WriteLine("AtbashDecryptor – simple Atbash (mirror‑alphabet) decoder");
        Console.WriteLine();
        Console.WriteLine("Usage:");
        Console.WriteLine("  AtbashDecryptor.exe [options]");
        Console.WriteLine();
        Console.WriteLine("Options:");
        Console.WriteLine("  -s, --skip-empty   Do not output or count completely empty lines.");
        Console.WriteLine("  -h, --help         Show this help message and exit.");
        Console.WriteLine();
        Console.WriteLine("Input format:");
        Console.WriteLine("  First line  – integer N, the number of following lines.");
        Console.WriteLine("  Next N lines – the text to decode.");
        Console.WriteLine();
        Console.WriteLine("The program prints the decoded lines and finally prints");
        Console.WriteLine("\"Secure\" if at least half of the alphabetic characters are");
        Console.WriteLine("changed by the Atbash substitution; otherwise it prints");
        Console.WriteLine("\"Insecure\".");
    }
}
```

*What changed?*  

* Added a loop that looks for `-h` or `--help`.  
* If found, `PrintHelp()` is called and the program returns immediately.  
* The help text is kept short but lists the `--skip-empty` switch and explains the program’s purpose.

