      opacity: 0;
      pointer-events: none;
      animation: pulse 0.4s ease-out forwards;
    }

    @keyframes pulse {
      0% { 
        left: calc(100% - 2px); 
        opacity: 0.8;
        width: 2px;
      }
      100% { 
        left: 0; 
        opacity: 0;
        width: 100%;
      }
    }
  </style>
</head>
<body>
