  <script>
    const terminal = document.getElementById('terminal');
    let lastSpaceTime = 0;

    terminal.addEventListener('keydown', (e) => {
      // Only trigger on spacebar with typing rhythm
      if (e.key === ' ' && Date.now() - lastSpaceTime > 300) {
        lastSpaceTime = Date.now();

        // Create holographic pulse at current caret position
        const pulse = document.createElement('div');
        pulse.className = 'pulse';

        // Position pulse at caret's horizontal position
        const rect = terminal.getBoundingClientRect();
        const caretX = window.getSelection().getRangeAt(0).getBoundingClientRect().left - rect.left;

        pulse.style.left = `${caretX}px`;
        terminal.appendChild(pulse);

        // Clean up after animation
        setTimeout(() => pulse.remove(), 400);
      }
    });
  </script>
</body>
</html>
