### 4.1 Десериализация (JSON → объект)

```java
import com.fasterxml.jackson.databind.ObjectMapper;

public class JacksonDeserializeDemo {
    public static void main(String[] args) throws Exception {
        String json = """
        {
            "items": [
                { "surname": "Khadiullin", "role": "student" },
                { "surname": "Gruzdev",   "role": "student" },
                { "surname": "Nazarov",   "role": "student" },
                { "surname": "Turkov",    "role": "lector" }
            ]
        }
        """;

        ObjectMapper mapper = new ObjectMapper();
        HumanResourceCatalogModels catalog = mapper.readValue(json, HumanResourceCatalogModels.class);

        System.out.println("Десериализовано, элементов: " + catalog.getItems().size());
    }
}
```

### 4.2 Сериализация (объект → JSON)

```java
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;

public class JacksonSerializeDemo {
    public static void main(String[] args) throws Exception {
        // 1️⃣ Сначала создаём объект (можно взять из ManualDemo)
        List<HumanResourceCatalogItems> list = List.of(
                new HumanResourceCatalogItems("Khadiullin", "student"),
                new HumanResourceCatalogItems("Gruzdev",   "student"),
                new HumanResourceCatalogItems("Nazarov",   "student"),
                new HumanResourceCatalogItems("Turkov",    "lector")
        );
        HumanResourceCatalogModels catalog = new HumanResourceCatalogModels(list);

        // 2️⃣ Сериализуем
        ObjectMapper mapper = new ObjectMapper();
        mapper.enable(SerializationFeature.INDENT_OUTPUT); // красивый вывод
        String json = mapper.writeValueAsString(catalog);

        System.out.println(json);
    }
}
```

