Below is a **single, self‑contained HTML file** that you can drop into any folder and open in a browser.  

* It works with a normal `<textarea>` **and** with a `<div contenteditable>` (the latter is easier to style because we can read the exact caret coordinates).  
* When the user presses **Space** or **Enter**, a thin “laser‑shot” (a colourful gradient line) is created at the caret, sweeps to the right edge of the field and fades out.  
* The animation is pure CSS, the JavaScript only creates the element and removes it when the animation ends –‑ no layout thrashing, so the page stays fast.  

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Laser‑Shot on Space / Enter</title>
<style>
  body{
    font-family:Arial,Helvetica,sans-serif;
    background:#111;
    color:#eee;
    display:flex;
    flex-direction:column;
    align-items:center;
    gap:2rem;
    padding:2rem;
  }
  h1{margin:0;}
  .field{
    position:relative;               /* needed for the laser overlay */
    width:90%;
    max-width:600px;
  }
  textarea,
  .editable{
    width:100%;
    min-height:120px;
    padding:0.8rem;
    font-size:1rem;
    line-height:1.5;
    border:2px solid #555;
    border-radius:6px;
    background:#222;
    color:#eee;
    resize:vertical;
    box-sizing:border-box;
    overflow:auto;
  }
  textarea{
    /* textarea text can’t be styled per‑character, so we use an overlay */
    background:transparent;          /* the overlay will show the gradient */
  }
  .editable{
    outline:none;
  }

  /* -------------------------------------------------
     Laser – a thin gradient line that moves right & fades
     ------------------------------------------------- */
  .laser{
    position:absolute;
    height:3px;               /* thickness of the laser */
    background:linear-gradient(90deg,
                #ff0066,
                #ffcc00,
                #00ffcc,
                #0066ff);
    pointer-events:none;     /* never block clicks / selection */
    animation:laser-move 0.6s ease-out forwards;
    opacity:0;                /* start invisible –‑ will be set to 1 by JS */
  }

  @keyframes laser-move{
    0%{
      left:var(--laser-start);
      width:0;
      opacity:1;
    }
    30%{
      width:calc(100% - var(--laser-start));
    }
    100%{
      left:100%;
      width:0;
      opacity:0;
    }
  }
</style>
</head>
<body>

<h1>Choir Sign‑up – Laser Shot Demo</h1>

<div class="field">
  <textarea id="ta" placeholder="Type your name… (press Space or Enter)"></textarea>
</div>

<div class="field">
  <div id="editable" class="editable" contenteditable="true"
       placeholder="Or use this content‑editable div…"></div>
</div>

<script>
/* -------------------------------------------------
   Utility: get caret coordinates inside a textarea
   ------------------------------------------------- */
function getCaretPosInTextarea(textarea) {
  const {selectionStart} = textarea;
  // Create a dummy div that mirrors the textarea's style
  const div = document.createElement('div');
  const style = getComputedStyle(textarea);
  for (const prop of style) div.style[prop] = style[prop];
  div.style.position = 'absolute';
  div.style.visibility = 'hidden';
  div.style.whiteSpace = 'pre-wrap';
  div.style.wordWrap = 'break-word';
  div.textContent = textarea.value.substring(0, selectionStart);
  document.body.appendChild(div);
  const span = document.createElement('span');
  // Insert a zero‑width character to get the exact caret location
  span.textContent = '\u200b';
  div.appendChild(span);
  const rect = span.getBoundingClientRect();
  const textareaRect = textarea.getBoundingClientRect();
  document.body.removeChild(div);
  return {
    x: rect.left - textareaRect.left + textarea.scrollLeft,
    y: rect.top - textareaRect.top + textarea.scrollTop
  };
}

/* -------------------------------------------------
   Utility: get caret coordinates inside a contenteditable
   ------------------------------------------------- */
function getCaretPosInEditable(editable) {
  const sel = window.getSelection();
  if (!sel.rangeCount) return null;
  const range = sel.getRangeAt(0).cloneRange();
  range.collapse(true);
  const rect = range.getClientRects()[0];
  const containerRect = editable.getBoundingClientRect();
  if (!rect) { // empty line –‑ fallback to top‑left of container
    return {x:0, y:0};
  }
  return {
    x: rect.left - containerRect.left + editable.scrollLeft,
    y: rect.top - containerRect.top + editable.scrollTop
  };
}

/* -------------------------------------------------
   Core: create the laser element at (x,y) inside container
   ------------------------------------------------- */
function fireLaser(container, x, y) {
  const laser = document.createElement('div');
  laser.className = 'laser';
  // Position vertically in the middle of the line height
  const lineHeight = parseFloat(getComputedStyle(container).lineHeight) || 20;
  laser.style.top = `${y + lineHeight/2 - 1.5}px`; // -1.5 to centre 3px height
  // CSS custom property for the start position (as a % of container width)
  const startPct = (x / container.clientWidth) * 100;
  laser.style.setProperty('--laser-start', `${startPct}%`);
  laser.style.opacity = '1';
  container.appendChild(laser);
  laser.addEventListener('animationend', () => laser.remove());
}

/* -------------------------------------------------
   Event handling for both fields
   ------------------------------------------------- */
function attachLaser(field, getCaretPos) {
  field.addEventListener('keydown', e => {
    if (e.key === 'Enter' || e.key === ' ') {
      // Defer to next tick so the caret has moved (esp. for Enter)
      setTimeout(() => {
        const pos = getCaretPos(field);
        if (!pos) return;
        fireLaser(field, pos.x, pos.y);
      }, 0);
    }
  });
}

/* -------------------------------------------------
   Initialise
   ------------------------------------------------- */
document.addEventListener('DOMContentLoaded', () => {
  const ta = document.getElementById('ta');
  const editable = document.getElementById('editable');

  // Wrap each field in its .field container (already done in markup)
  const taContainer = ta.closest('.field');
  const editContainer = editable.closest('.field');

  attachLaser(ta, () => getCaretPosInTextarea(ta));
  attachLaser(editable, () => getCaretPosInEditable(editable));

  // Optional: placeholder for contenteditable (pure CSS fallback)
  const placeholderStyle = document.createElement('style');
  placeholderStyle.textContent = `
    .editable:empty:before{
      content:attr(placeholder);
      color:#777;
    }
  `;
  document.head.appendChild(placeholderStyle);
});
</script>
</body>
</html>
```

### How it works

| Step | What happens |
|------|--------------|
| **1. Detect key** | `keydown` listener watches for **Space** (`' '` ) or **Enter** (`'Enter'`). |
| **2. Find caret** | • For a `<textarea>` we duplicate its styling in an off‑screen `<div>` and measure the caret using a zero‑width `<span>`. <br>• For a `contenteditable` we use the native `Range.getClientRects()` to get the exact pixel location. |
| **3. Create laser** | A `<div class="laser">` is inserted into the same `.field` container. Its vertical position is set to the caret’s line‑height centre. The start‑position is stored in a CSS custom property `--laser-start`. |
| **4. Animate** | The CSS `@keyframes laser‑move` expands the line from the start point to the right edge, then shrinks it while fading out. The animation runs **0.6 s** and is hardware‑accelerated (only `transform`‑friendly properties). |
| **5. Clean‑up** | When the animation ends the element removes itself, leaving the DOM tidy. |

### Why both textarea **and** contenteditable?

* **Textarea** – the classic form control. It works everywhere, but you can’t style the text itself (e.g., add a coloured underline inside the field). The overlay technique keeps the laser visible without interfering with the native textarea behavior.
* **Contenteditable** – gives pixel‑perfect caret coordinates, so the laser lines up exactly with the text. It also lets you style the text (fonts, colors) as you wish, making the effect look cleaner on modern browsers.

Feel free to copy the file, tweak the colors, thickness, or animation duration, and drop it into your choir‑sign‑up page. Enjoy the laser‑powered feedback!

To check if a button is **enabled during the initial launch of your WPF application** (i.e., its state when the window first appears), follow these steps. The solution depends on whether you're checking the **transient initial state** (when the app starts) or a **persistent "first run ever"** scenario (like a first-time user experience). Below are both approaches:

---

### 🔍 1. **Check Button State at Application Startup (Transient Initial State)**
This checks if the button is enabled **the moment the window loads** (e.g., for debugging or initialization logic).  
**This is the most common interpretation of your question.**

#### ✅ Best Practice: Use the `Loaded` Event
The `Loaded` event fires **after** the UI is fully initialized (including bindings), ensuring you get the *actual* enabled state.

```csharp
public partial class MainWindow : Window
{
    public MainWindow()
    {
        InitializeComponent();
        Loaded += MainWindow_Loaded; // Subscribe to Loaded event
    }

    private void MainWindow_Loaded(object sender, RoutedEventArgs e)
    {
        // Check if Button is enabled RIGHT NOW (when window first appears)
        bool isButtonEnabled = MyButton.IsEnabled;

        if (isButtonEnabled)
        {
            // Button is enabled on first load
            Debug.WriteLine("Button is ENABLED on startup");
        }
        else
        {
            // Button is disabled on first load
            Debug.WriteLine("Button is DISABLED on startup");
        }
    }
}
```

#### 📌 Key Notes:
- **Why `Loaded`?**  
  The constructor (`MainWindow()`) runs **before** the UI is rendered. Bindings/commands might not have updated `IsEnabled` yet. `Loaded` guarantees the UI is ready.
- **If using MVVM with Commands**:  
  The button's state is often controlled by `ICommand.CanExecute`. Check the command's initial state in your ViewModel:
  ```csharp
  // In your ViewModel constructor
  public MyViewModel()
  {
      MyCommand = new RelayCommand(Execute, () => CanExecute); // CanExecute is false initially?
      Debug.WriteLine($"Command can execute: {MyCommand.CanExecute(null)}");
  }
  ```

---

### 🌐 2. **Check "First Run Ever" (Persistent First Launch)**
If you mean **"is this the very first time the user ever launched the app?"** (e.g., for a tutorial), use **application settings**:

#### Step 1: Create a Setting to Track First Run
1. Go to **Project Properties** → **Settings**.
2. Add a setting:  
   - Name: `IsFirstRun`  
   - Type: `bool`  
   - Scope: `User`  
   - Value: `true` (default)

#### Step 2: Check in `App.xaml.cs`
```csharp
protected override void OnStartup(StartupEventArgs e)
{
    if (Properties.Settings.Default.IsFirstRun)
    {
        // This is the FIRST time the app is launched
        Properties.Settings.Default.IsFirstRun = false; // Disable for future runs
        Properties.Settings.Default.Save();

        // Now check if your button is enabled in the main window
        var mainWindow = new MainWindow();
        mainWindow.Show();

        // Access the button AFTER the window is shown (use Dispatcher)
        mainWindow.Dispatcher.Invoke(() =>
        {
            bool isButtonEnabled = mainWindow.MyButton.IsEnabled;
            Debug.WriteLine($"First run: Button enabled = {isButtonEnabled}");
        });
    }
    else
    {
        // Not the first run
        base.OnStartup(e);
    }
}
```

#### ⚠️ Important Caveats:
- **Don't access UI elements before `mainWindow.Show()`** – the window isn't rendered yet.
- **Use `Dispatcher.Invoke`** to safely access UI elements from `OnStartup`.
- This approach **only works for "first launch ever"**, not the transient initial state of the button.

---

### 🔧 Common Pitfalls & Fixes
| Issue                          | Solution                                                                 |
|--------------------------------|--------------------------------------------------------------------------|
| Button state changes later     | Check in `Loaded`, not the constructor (bindings may not be applied yet). |
| Command-based enablement       | Verify `CanExecute` logic in your ViewModel/command.                     |
| Async initialization           | Delay checks until async operations finish (use `async/await` in `Loaded`). |
| Binding overrides `IsEnabled`  | Inspect your XAML: `<Button IsEnabled="{Binding ...}">` may override hard-coded values. |

---

### 💡 Pro Tip: Debugging Button State
Add this to your XAML to **visually confirm** the initial state:
```xml
<Button x:Name="MyButton" 
        Content="Test" 
        IsEnabled="False" <!-- Set your initial state here -->
        Background="{Binding IsEnabled, 
                     RelativeSource={RelativeSource Self}, 
                     Converter={StaticResource BoolToBrushConverter}}"/>
```
Use a `BoolToBrushConverter` to turn `IsEnabled` into a color (e.g., red for disabled, green for enabled).

---

### Summary
- For **"is the button enabled when the window first appears?"** → Use the `Loaded` event.  
- For **"is this the user's very first launch of the app?"** → Use `Properties.Settings` + check in `OnStartup`.  

Most likely, you need the **`Loaded` event approach** (Section 1). This covers 95% of cases where developers need to verify initial UI state. If you're using MVVM, ensure your ViewModel's command logic reflects the intended initial state. 🚀

