class AmbientTemperatureIndicator {
  public:
    enum Unit { CELSIUS, FAHRENHEIT };
    enum Availability { ACTIVE, NOT_ACTIVE };
    enum ConversionError { NONE, INVALID_INPUT, OUT_OF_RANGE };

    AmbientTemperatureIndicator() : data(0), availability(ACTIVE), format(CELSIUS), conversionError(NONE) {}

    ConversionError setData(double temp, Unit unit) {
      conversionError = NONE;

      if (!isValidTemperature(temp, unit)) {
        conversionError = INVALID_INPUT;
        availability = NOT_ACTIVE;
        return conversionError;
      }

      double tempInCelsius = convertToCelsius(temp, unit);

      if (tempInCelsius < -50) {
        availability = NOT_ACTIVE;
        data = -45;
      } else if (tempInCelsius > 85) {
        availability = NOT_ACTIVE;
        data = 80;
      } else {
        availability = ACTIVE;
        data = tempInCelsius;
      }

      return conversionError;
    }

    double convertTemperature(double temp, Unit fromUnit, Unit toUnit) {
      if (fromUnit == toUnit) {
        return temp;
      }

      if (fromUnit == CELSIUS && toUnit == FAHRENHEIT) {
        return temp * 9.0 / 5.0 + 32;
      } else if (fromUnit == FAHRENHEIT && toUnit == CELSIUS) {
        return (temp - 32) * 5.0 / 9.0;
      }

      return temp;
    }

    void setFormat(Unit unit) { 
      format = unit;
      if (availability == ACTIVE && format == FAHRENHEIT) {
        data = convertTemperature(data, CELSIUS, FAHRENHEIT);
      } else if (availability == ACTIVE && format == CELSIUS) {
        data = convertTemperature(data, FAHRENHEIT, CELSIUS);
      }
    }

    double getData() const { return data; }
    Availability getAvailability() const { return availability; }
    Unit getFormat() const { return format; }
    ConversionError getConversionError() const { return conversionError; }

  private:
    double data;
    Availability availability;
    Unit format;
    ConversionError conversionError;

    bool isValidTemperature(double temp, Unit unit) {
      if (unit == CELSIUS) {
        return temp >= -100 && temp <= 100;
      } else {
        return temp >= -148 && temp <= 212;
      }
    }

    double convertToCelsius(double temp, Unit unit) {
      if (unit == CELSIUS) {
        return temp;
      } else {
        return (temp - 32) * 5.0 / 9.0;
      }
    }
};

