**prcinfo – process‑tree inspector**  

```c
/*
 * prcinfo.c
 *
 * A tiny utility that checks whether a set of PIDs are descendants of a
 * given root PID and (optionally) prints extra information about the
 * first target PID.
 *
 *  usage:
 *      prcinfo <root_process> <process_id1> [process_id2] … [process_idN] [OPTION]
 *
 *  where 1 ≤ N ≤ 5 and OPTION is one of
 *      -nd   non‑direct descendants of process_id1
 *      -dd   immediate (direct) children of process_id1
 *      -sb   siblings of process_id1
 *      -sz   sibling processes that are zombies
 *      -gc   grandchildren of process_id1
 *      zz    “Defunct” / “Not Defunct” status of process_id1
 *      zc    direct descendants of process_id1 that are zombies
 *
 *  All PIDs must be descendants of the current shell (i.e. of $$) and the
 *  program must be run with sufficient permissions to read /proc/<pid>/stat.
 *
 *  Compile:
 *      gcc -Wall -Wextra -O2 -o prcinfo prcinfo.c
 */

#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <dirent.h>
#include <errno.h>
#include <unistd.h>
#include <sys/types.h>
#include <limits.h>

/* --------------------------------------------------------------------- *
 *  Data structures
 * --------------------------------------------------------------------- */
typedef struct ProcInfo {
    pid_t pid;          /* process id                               */
    pid_t ppid;         /* parent process id                        */
    char state;         /* process state – the first character of   */
                        /* the “State:” field in /proc/<pid>/status */
} ProcInfo;

/* A simple dynamic array for ProcInfo objects */
typedef struct ProcTable {
    ProcInfo *data;
    size_t    used;
    size_t    size;
} ProcTable;

/* --------------------------------------------------------------------- *
 *  Helper functions for the ProcTable
 * --------------------------------------------------------------------- */
static void pt_init(ProcTable *pt, size_t init_size)
{
    pt->data = malloc(init_size * sizeof(ProcInfo));
    if (!pt->data) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    pt->used = 0;
    pt->size = init_size;
}

static void pt_append(ProcTable *pt, ProcInfo pi)
{
    if (pt->used == pt->size) {
        pt->size *= 2;
        pt->data = realloc(pt->data, pt->size * sizeof(ProcInfo));
        if (!pt->data) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
    }
    pt->data[pt->used++] = pi;
}

/* --------------------------------------------------------------------- *
 *  ProcInfo extraction
 * --------------------------------------------------------------------- */

/* read /proc/<pid>/stat and fill a ProcInfo structure.
 * Returns 0 on success, -1 on failure (e.g. permission denied).          */
static int read_proc_info(pid_t pid, ProcInfo *out)
{
    char path[PATH_MAX];
    FILE *fp;
    char comm[256];
    long unsigned int dummy;
    int scanned;

    snprintf(path, sizeof(path), "/proc/%d/stat", pid);
    fp = fopen(path, "r");
    if (!fp)
        return -1;               /* most likely permission problem */

    /* /proc/<pid>/stat format (excerpt):
     *   pid (comm) state ppid ...
     *   We only need pid, state and ppid.
     */
    scanned = fscanf(fp,
                     "%d "          /* pid               */
                     "%255s "       /* comm (in parentheses) */
                     " %c "         /* state             */
                     "%d",          /* ppid              */
                     &out->pid, comm, &out->state, &out->ppid);
    fclose(fp);
    if (scanned != 4)
        return -1;

    return 0;
}

/* Build a table that contains a snapshot of all processes visible to us. */
static void build_proc_table(ProcTable *pt)
{
    DIR *proc = opendir("/proc");
    struct dirent *ent;

    if (!proc) {
        perror("opendir /proc");
        exit(EXIT_FAILURE);
    }

    pt_init(pt, 256);          /* start with a modest size */

    while ((ent = readdir(proc)) != NULL) {
        if (!isdigit(ent->d_name[0]))
            continue;          /* not a PID directory */

        pid_t pid = (pid_t)strtol(ent->d_name, NULL, 10);
        ProcInfo pi;
        if (read_proc_info(pid, &pi) == 0)
            pt_append(pt, pi);
        /* If we cannot read a process (e.g. kernel thread), we silently skip it. */
    }
    closedir(proc);
}

/* --------------------------------------------------------------------- *
 *  Lookup helpers
 * --------------------------------------------------------------------- */
static const ProcInfo *find_proc(const ProcTable *pt, pid_t pid)
{
    for (size_t i = 0; i < pt->used; ++i)
        if (pt->data[i].pid == pid)
            return &pt->data[i];
    return NULL;               /* not found (perhaps disappeared) */
}

/* Return the parent pid of a given pid, or -1 if unknown. */
static pid_t get_ppid(const ProcTable *pt, pid_t pid)
{
    const ProcInfo *p = find_proc(pt, pid);
    return p ? p->ppid : (pid_t)-1;
}

/* Return 1 if child is a descendant (any depth) of ancestor, 0 otherwise. */
static int is_descendant(const ProcTable *pt, pid_t ancestor, pid_t child)
{
    pid_t cur = child;
    while (cur > 0 && cur != ancestor) {
        cur = get_ppid(pt, cur);
        if (cur == (pid_t)-1)      /* we hit a process that vanished */
            return 0;
    }
    return cur == ancestor;
}

/* --------------------------------------------------------------------- *
 *  Collection helpers (all work on the snapshot stored in ProcTable)
 * --------------------------------------------------------------------- */

/* Direct children of a pid */
static void collect_children(const ProcTable *pt, pid_t pid, ProcTable *out)
{
    pt_init(out, 16);
    for (size_t i = 0; i < pt->used; ++i)
        if (pt->data[i].ppid == pid)
            pt_append(out, pt->data[i]);
}

/* All descendants (including direct children) */
static void collect_descendants(const ProcTable *pt, pid_t pid, ProcTable *out)
{
    pt_init(out, 32);
    for (size_t i = 0; i < pt->used; ++i) {
        if (is_descendant(pt, pid, pt->data[i].pid) && pt->data[i].pid != pid)
            pt_append(out, pt->data[i]);
    }
}

/* Non‑direct descendants = all descendants except immediate children */
static void collect_nondirect_descendants(const ProcTable *pt,
                                          pid_t pid,
                                          ProcTable *out)
{
    ProcTable children;
    collect_children(pt, pid, &children);
    pt_init(out, 32);
    for (size_t i = 0; i < pt->used; ++i) {
        if (pt->data[i].pid == pid)
            continue;
        if (!is_descendant(pt, pid, pt->data[i].pid))
            continue;
        /* skip if it is a direct child */
        int is_child = 0;
        for (size_t j = 0; j < children.used; ++j)
            if (children.data[j].pid == pt->data[i].pid) {
                is_child = 1;
                break;
            }
        if (!is_child)
            pt_append(out, pt->data[i]);
    }
    free(children.data);
}

/* Grandchildren = children of children */
static void collect_grandchildren(const ProcTable *pt,
                                  pid_t pid,
                                  ProcTable *out)
{
    ProcTable children;
    collect_children(pt, pid, &children);
    pt_init(out, 16);
    for (size_t i = 0; i < children.used; ++i) {
        ProcTable gc;
        collect_children(pt, children.data[i].pid, &gc);
        for (size_t j = 0; j < gc.used; ++j)
            pt_append(out, gc.data[j]);
        free(gc.data);
    }
    free(children.data);
}

/* Siblings (processes sharing the same parent) */
static void collect_siblings(const ProcTable *pt,
                             pid_t pid,
                             ProcTable *out)
{
    const ProcInfo *p = find_proc(pt, pid);
    if (!p) {
        pt_init(out, 0);
        return;
    }
    pid_t parent = p->ppid;
    pt_init(out, 8);
    for (size_t i = 0; i < pt->used; ++i) {
        if (pt->data[i].ppid == parent && pt->data[i].pid != pid)
            pt_append(out, pt->data[i]);
    }
}

/* Sibling zombies */
static void collect_sibling_zombies(const ProcTable *pt,
                                    pid_t pid,
                                    ProcTable *out)
{
    ProcTable sib;
    collect_siblings(pt, pid, &sib);
    pt_init(out, 8);
    for (size_t i = 0; i < sib.used; ++i)
        if (sib.data[i].state == 'Z')
            pt_append(out, sib.data[i]);
    free(sib.data);
}

/* Direct descendants that are zombies (children only) */
static void collect_zombie_children(const ProcTable *pt,
                                    pid_t pid,
                                    ProcTable *out)
{
    ProcTable children;
    collect_children(pt, pid, &children);
    pt_init(out, 8);
    for (size_t i = 0; i < children.used; ++i)
        if (children.data[i].state == 'Z')
            pt_append(out, children.data[i]);
    free(children.data);
}

/* --------------------------------------------------------------------- *
 *  Printing helpers
 * --------------------------------------------------------------------- */
static void print_pid_list(const char *title, const ProcTable *list)
{
    printf("%s:", title);
    if (list->used == 0) {
        printf(" <none>\n");
        return;
    }
    for (size_t i = 0; i < list->used; ++i) {
        printf(" %d", list->data[i].pid);
    }
    putchar('\n');
}

/* --------------------------------------------------------------------- *
 *  Argument handling
 * --------------------------------------------------------------------- */
static int is_number(const char *s)
{
    if (!s || *s == '\0')
        return 0;
    while (*s) {
        if (!isdigit((unsigned char)*s))
            return 0;
        ++s;
    }
    return 1;
}

/* Print usage and exit */
static void usage(const char *prog)
{
    fprintf(stderr,
        "Usage: %s <root_process> <process_id1> [process_id2] ... [process_idN] [OPTION]\n"
        "\n"
        "   root_process   PID of the root of the tree to be examined.\n"
        "   process_idX    1‑5 target PIDs (must be descendants of root_process).\n"
        "   OPTION         one of:\n"
        "        -nd   non‑direct descendants of process_id1\n"
        "        -dd   direct children of process_id1\n"
        "        -sb   siblings of process_id1\n"
        "        -sz   sibling zombies of process_id1\n"
        "        -gc   grandchildren of process_id1\n"
        "        zz    \"Defunct\" / \"Not Defunct\" status of process_id1\n"
        "        zc    direct children of process_id1 that are zombies\n"
        , prog);
    exit(EXIT_FAILURE);
}

/* --------------------------------------------------------------------- *
 *  Main
 * --------------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    if (argc < 3)               /* at least prog, root, one target */
        usage(argv[0]);

    /* ----------------------------------------------------------------- *
     *  Parse root PID and target PIDs
     * ----------------------------------------------------------------- */
    if (!is_number(argv[1])) {
        fprintf(stderr, "error: root_process must be a number\n");
        return EXIT_FAILURE;
    }
    pid_t root_pid = (pid_t)strtol(argv[1], NULL, 10);

    /* collect up to five target PIDs */
    pid_t targets[5];
    size_t n_targets = 0;
    int opt_index = -1;         /* index of the optional flag (if any) */

    for (int i = 2; i < argc; ++i) {
        if (argv[i][0] == '-' || strcmp(argv[i], "zz") == 0 || strcmp(argv[i], "zc") == 0) {
            opt_index = i;
            break;
        }
        if (!is_number(argv[i])) {
            fprintf(stderr, "error: target PID \"%s\" is not numeric\n", argv[i]);
            return EXIT_FAILURE;
        }
        if (n_targets >= 5) {
            fprintf(stderr, "error: at most five target PIDs are allowed\n");
            return EXIT_FAILURE;
        }
        targets[n_targets++] = (pid_t)strtol(argv[i], NULL, 10);
    }

    /* If the loop stopped on a flag, the rest of the arguments must be empty */
    if (opt_index != -1 && opt_index != argc - 1) {
        fprintf(stderr, "error: only a single optional flag may be supplied\n");
        return EXIT_FAILURE;
    }

    const char *opt = (opt_index != -1) ? argv[opt_index] : NULL;

    /* ----------------------------------------------------------------- *
     *  Build a snapshot of the process table once – all later queries are
     *  performed on this static view.
     * ----------------------------------------------------------------- */
    ProcTable proc_table;
    build_proc_table(&proc_table);

    /* ----------------------------------------------------------------- *
     *  Verify that each target is a descendant of root_pid.
     * ----------------------------------------------------------------- */
    for (size_t i = 0; i < n_targets; ++i) {
        pid_t t = targets[i];
        const ProcInfo *info = find_proc(&proc_table, t);
        if (!info) {
            fprintf(stderr, "error: target PID %d does not exist or cannot be accessed\n", t);
            free(proc_table.data);
            return EXIT_FAILURE;
        }
        if (!is_descendant(&proc_table, root_pid, t)) {
            fprintf(stderr, "error: PID %d is not a descendant of root PID %d\n", t, root_pid);
            free(proc_table.data);
            return EXIT_FAILURE;
        }
        printf("PID: %d, PPID: %d\n", info->pid, info->ppid);
    }

    /* ----------------------------------------------------------------- *
     *  If an option was supplied, act on the *first* target only.
     * ----------------------------------------------------------------- */
    if (opt) {
        pid_t first = targets[0];
        const ProcInfo *first_info = find_proc(&proc_table, first);
        if (!first_info) {
            fprintf(stderr, "error: first target PID %d vanished\n", first);
            free(proc_table.data);
            return EXIT_FAILURE;
        }

        if (strcmp(opt, "-nd") == 0) {
            ProcTable nd;
            collect_nondirect_descendants(&proc_table, first, &nd);
            print_pid_list("Non‑direct descendants", &nd);
            free(nd.data);
        }
        else if (strcmp(opt, "-dd") == 0) {
            ProcTable children;
            collect_children(&proc_table, first, &children);
            print_pid_list("Direct children", &children);
            free(children.data);
        }
        else if (strcmp(opt, "-sb") == 0) {
            ProcTable sib;
            collect_siblings(&proc_table, first, &sib);
            print_pid_list("Siblings", &sib);
            free(sib.data);
        }
        else if (strcmp(opt, "-sz") == 0) {
            ProcTable sz;
            collect_sibling_zombies(&proc_table, first, &sz);
            print_pid_list("Sibling zombies", &sz);
            free(sz.data);
        }
        else if (strcmp(opt, "-gc") == 0) {
            ProcTable gc;
            collect_grandchildren(&proc_table, first, &gc);
            print_pid_list("Grandchildren", &gc);
            free(gc.data);
        }
        else if (strcmp(opt, "zz") == 0) {
            printf("Status of %d: %s\n",
                   first,
                   (first_info->state == 'Z') ? "Defunct" : "Not Defunct");
        }
        else if (strcmp(opt, "zc") == 0) {
            ProcTable zc;
            collect_zombie_children(&proc_table, first, &zc);
            print_pid_list("Zombie direct children", &zc);
            free(zc.data);
        }
        else {
            fprintf(stderr, "error: unknown option \"%s\"\n", opt);
            free(proc_table.data);
            return EXIT_FAILURE;
        }
    }

    free(proc_table.data);
    return EXIT_SUCCESS;
}
```

### How the program works

| Step | What the code does |
|------|--------------------|
| **1. Build a snapshot** | `build_proc_table()` walks `/proc`, reads each numeric directory’s `stat` file and stores `pid`, `ppid` and the first character of the *State* field (`R`, `S`, `Z`, …). |
| **2. Argument parsing** | The first argument is the *root* PID, the next 1‑5 arguments are target PIDs, and an optional final argument is the flag (`-nd`, `-dd`, `-sb`, `-sz`, `-gc`, `zz`, `zc`).  Numeric validation and the 5‑PID limit are enforced. |
| **3. Descendant verification** | For each target PID we call `is_descendant()` which walks the parent chain using the snapshot until it either reaches the root PID or hits `0`.  If any target fails, the program aborts with an explanatory error. |
| **4. Basic output** | For every validated target we print `PID: <pid>, PPID: <ppid>`. |
| **5. Optional flag handling** | Only the **first** target PID is examined for the optional flag.  Dedicated helper functions collect the requested sets of processes (children, grandchildren, non‑direct descendants, siblings, zombie siblings, zombie children).  The results are printed as a space‑separated list, or “\<none\>” if empty. |
| **6. Error handling** | All system calls (`opendir`, `fopen`, `malloc`, …) are checked.  Meaningful messages are written to `stderr` and the program exits with `EXIT_FAILURE` on error conditions (invalid PID, permission denied, malformed option, etc.). |
| **7. Clean‑up** | Dynamically allocated buffers are freed before exit. |

### Things to keep in mind

* The program works on any recent Linux kernel that provides the standard `/proc/<pid>/stat` interface.
* It only inspects processes that the invoking user can read; kernel threads or processes owned by another user may be silently omitted from the snapshot.
* Because the process table is captured once at start‑up, the output reflects a **consistent** view even if processes appear/disappear while the program runs.

Feel free to adapt the printing format, add colour, or extend the option set – the core logic (building a process table, walking parent links, and filtering) is already modularised. Happy hacking!

Below is a **stand‑alone C program** that

* reads a dense real matrix **A** (row‑major) from *stdin*,
* calls the LAPACK routine **`dgesvd`** that ATLAS ships as part of its LAPACK interface,
* returns the three SVD factors **U**, **Σ** (as a vector of singular values) and **Vᵀ**,
* prints the three factors to *stdout* in a simple human‑readable format.

The code works with ATLAS ≥ 3.10 (the version that ships the full LAPACK interface).  
If you prefer C++, just rename the file to *.cpp* and compile with the same flags – the code is pure C and therefore C++‑compatible.

---

## 1. Source code (`svd_atlas.c`)

```c
/*
 * svd_atlas.c
 *
 * Compute the Singular Value Decomposition of a real dense matrix using
 * the ATLAS LAPACK interface (dgesvd).
 *
 *   A  (m×n)  =  U (m×m) * Σ (m×n) * Vᵀ (n×n)
 *
 * Input format (stdin):
 *   m n                     <-- two integers, number of rows and columns
 *   a_11 a_12 ... a_1n      <-- first row, space‑ or newline‑separated
 *   a_21 a_22 ... a_2n
 *   ...
 *   a_m1 a_m2 ... a_mn
 *
 * Output format (stdout):
 *   ---- U (m×m) ----
 *   <m lines of m numbers>
 *   ---- singular values (min(m,n)) ----
 *   <list of values>
 *   ---- Vᵀ (n×n) ----
 *   <n lines of n numbers>
 *
 * Compile (example):
 *   gcc svd_atlas.c -o svd -O2 -llapack -lcblas -latlas -lm
 *
 * Run:
 *   ./svd < matrix.txt
 *
 * --------------------------------------------------------------
 *  Note: ATLAS supplies the LAPACK routine dgesvd via the
 *  "clapack.h" header.  The routine follows the standard LAPACK
 *  calling convention (column‑major storage).  Therefore we must
 *  copy the row‑major input matrix into a column‑major buffer before
 *  calling dgesvd, and copy the results back to row‑major for printing.
 * --------------------------------------------------------------
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <cblas.h>
#include <lapack.h>          /* ATLAS provides the LAPACK prototypes here */

/* ------------------------------------------------------------------ */
/* Helper: read a matrix from stdin (row‑major)                        */
static double *read_matrix(int m, int n)
{
    double *A = (double *)malloc(m * n * sizeof(double));
    if (!A) {
        fprintf(stderr, "Memory allocation failure for matrix A.\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < m * n; ++i) {
        if (scanf("%lf", &A[i]) != 1) {
            fprintf(stderr, "Failed to read element %d of the matrix.\n", i);
            free(A);
            exit(EXIT_FAILURE);
        }
    }
    return A;
}

/* ------------------------------------------------------------------ */
/* Helper: print a matrix in row‑major order                           */
static void print_matrix(const char *title, const double *M, int rows, int cols)
{
    printf("---- %s (%dx%d) ----\n", title, rows, cols);
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            printf("% .12e ", M[i * cols + j]);
        }
        putchar('\n');
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int m, n;

    /* --------------------------------------------------------------
       1) read dimensions
       -------------------------------------------------------------- */
    if (scanf("%d %d", &m, &n) != 2) {
        fprintf(stderr, "Failed to read matrix dimensions (m n).\n");
        return EXIT_FAILURE;
    }
    if (m <= 0 || n <= 0) {
        fprintf(stderr, "Matrix dimensions must be positive.\n");
        return EXIT_FAILURE;
    }

    /* --------------------------------------------------------------
       2) read the matrix (row‑major) and convert to column‑major
       -------------------------------------------------------------- */
    double *A_row = read_matrix(m, n);

    /* ATLAS/LAPACK expects column‑major storage.  Allocate a copy. */
    double *A = (double *)malloc(m * n * sizeof(double));
    if (!A) {
        fprintf(stderr, "Memory allocation failure for column‑major A.\n");
        free(A_row);
        return EXIT_FAILURE;
    }
    for (int i = 0; i < m; ++i)
        for (int j = 0; j < n; ++j)
            A[j * m + i] = A_row[i * n + j];   /* transpose while copying */

    free(A_row);   /* no longer needed */

    /* --------------------------------------------------------------
       3) allocate output buffers
       -------------------------------------------------------------- */
    int k = (m < n) ? m : n;               /* min(m,n) = number of singular values */
    double *S = (double *)malloc(k * sizeof(double));          /* singular values */
    double *U = (double *)malloc(m * m * sizeof(double));      /* left singular vectors */
    double *VT = (double *)malloc(n * n * sizeof(double));     /* right singular vectors transposed */
    double *work = NULL;
    int    lwork = -1;                     /* workspace query */
    int    info;

    if (!S || !U || !VT) {
        fprintf(stderr, "Memory allocation failure for S, U or VT.\n");
        free(A);
        free(S); free(U); free(VT);
        return EXIT_FAILURE;
    }

    /* --------------------------------------------------------------
       4) Workspace query (the routine returns optimal lwork in work[0])
       -------------------------------------------------------------- */
    double wkopt;
    dgesvd_("A", "A",   /* compute full U and Vᵀ */
            &m, &n,
            A, &m,
            S,
            U, &m,
            VT, &n,
            &wkopt, &lwork,
            &info);
    if (info != 0) {
        fprintf(stderr, "dgesvd workspace query failed, info = %d\n", info);
        free(A); free(S); free(U); free(VT);
        return EXIT_FAILURE;
    }
    lwork = (int)wkopt;
    work = (double *)malloc(lwork * sizeof(double));
    if (!work) {
        fprintf(stderr, "Failed to allocate work array of size %d.\n", lwork);
        free(A); free(S); free(U); free(VT);
        return EXIT_FAILURE;
    }

    /* --------------------------------------------------------------
       5) Actual SVD computation
       -------------------------------------------------------------- */
    dgesvd_("A", "A",
            &m, &n,
            A, &m,
            S,
            U, &m,
            VT, &n,
            work, &lwork,
            &info);
    if (info != 0) {
        fprintf(stderr, "dgesvd failed, info = %d\n", info);
        free(A); free(S); free(U); free(VT); free(work);
        return EXIT_FAILURE;
    }

    /* --------------------------------------------------------------
       6) Convert U and Vᵀ back to row‑major for printing
       -------------------------------------------------------------- */
    double *U_row = (double *)malloc(m * m * sizeof(double));
    double *VT_row = (double *)malloc(n * n * sizeof(double));
    if (!U_row || !VT_row) {
        fprintf(stderr, "Memory allocation failure for row‑major results.\n");
        free(A); free(S); free(U); free(VT); free(work);
        free(U_row); free(VT_row);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < m; ++i)
        for (int j = 0; j < m; ++j)
            U_row[i * m + j] = U[j * m + i];   /* transpose back */

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            VT_row[i * n + j] = VT[j * n + i]; /* transpose back */

    /* --------------------------------------------------------------
       7) Print results
       -------------------------------------------------------------- */
    print_matrix("U", U_row, m, m);

    printf("---- singular values (min(m,n) = %d) ----\n", k);
    for (int i = 0; i < k; ++i)
        printf("% .12e ", S[i]);
    putchar('\n');

    print_matrix("Vᵀ", VT_row, n, n);

    /* --------------------------------------------------------------
       8) Clean up
       -------------------------------------------------------------- */
    free(A); free(S); free(U); free(VT);
    free(work);
    free(U_row); free(VT_row);

    return EXIT_SUCCESS;
}
```

