% 5. 可视化预测结果
figure;
plot(1:size(test_y, 2), test_y(1,:), 'b-o', 'LineWidth', 1.5, 'DisplayName', '真实值');
hold on;
plot(1:size(test_predict, 2), test_predict(1,:), 'r--s', 'LineWidth', 1.5, 'DisplayName', '预测值');
xlabel('样本序号'); ylabel('目标值');
title(['ACO-BP预测结果 (R² = ' num2str(r2, '%.4f') ')']);
