```dart
import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';
import 'package:flutter/scheduler.dart';
import 'package:provider/provider.dart';

// ---- QR‑Scanner‑Pakete -------------------------------------------------
import 'package:code_scan/code_scan.dart';
import 'package:mobile_scanner/mobile_scanner.dart';

// ----------------------------------------------------------------------
// 1️⃣  Generic Backend Interface
// ----------------------------------------------------------------------
abstract class QrScannerBackend {
  /// Build the preview widget. The widget receives the callbacks that the UI
  /// needs to react to.
  Widget buildView({
    required Key viewKey,
    required void Function(String? code) onDetect,
    required Future<bool> Function() onAccessDenied,
    required void Function() onError,
  });

  Future<void> pauseCamera();
  Future<void> resumeCamera();
  Future<void> dispose();

  // ---- optional helpers (Zoom / Torch) --------------------------------
  Future<void> toggleTorch() async {}
  Future<void> setZoom(double factor) async {}
}

// ----------------------------------------------------------------------
// 2️⃣  Code‑Scan‑Backend (dein aktuelles Plugin)
// ----------------------------------------------------------------------
class CodeScanBackend implements QrScannerBackend {
  final CodeScannerController _controller = CodeScannerController();

  @override
  Widget buildView({
    required Key viewKey,
    required void Function(String? code) onDetect,
    required Future<bool> Function() onAccessDenied,
    required void Function() onError,
  }) {
    return CodeScanner(
      key: viewKey,
      controller: _controller,
      formats: const [BarcodeFormat.qrCode],
      scanInterval: const Duration(milliseconds: 500),
      onScan: (code, _, __) => onDetect(code),
      onAccessDenied: (_, __) async => await onAccessDenied(),
      onError: (_, __) => onError(),
      overlay: Container(),
    );
  }

  @override
  Future<void> pauseCamera() => _controller.pauseCamera();

  @override
  Future<void> resumeCamera() => _controller.resumeCamera();

  @override
  Future<void> dispose() => _controller.dispose();

  // Torch / Zoom sind im `code_scan`‑Plugin nicht direkt verfügbar,
  // hier könntest du eigene Logik einbauen, falls du das brauchst.
}

// ----------------------------------------------------------------------
// 3️⃣  Mobile‑Scanner‑Backend (Alternative)
// ----------------------------------------------------------------------
class MobileScannerBackend implements QrScannerBackend {
  final MobileScannerController _controller = MobileScannerController();

  @override
  Widget buildView({
    required Key viewKey,
    required void Function(String? code) onDetect,
    required Future<bool> Function() onAccessDenied,
    required void Function() onError,
  }) {
    return MobileScanner(
      key: viewKey,
      controller: _controller,
      // MobileScanner liefert ein BarcodeCapture‑Objekt → wir holen den String
      onDetect: (capture) {
        final raw = capture.barcodes.first.rawValue;
        onDetect(raw);
      },
    );
  }

  @override
  Future<void> pauseCamera() => _controller.stop();

  @override
  Future<void> resumeCamera() => _controller.start();

  @override
  Future<void> dispose() => _controller.dispose();

  // MobileScanner hat eingebaute Torch‑ und Zoom‑Methoden:
  @override
  Future<void> toggleTorch() async => _controller.toggleTorch();

  @override
  Future<void> setZoom(double factor) async => _controller.setZoom(factor);
}

// ----------------------------------------------------------------------
// 4️⃣  Provider‑Model – hält das aktuell ausgewählte Backend
// ----------------------------------------------------------------------
class ScannerProvider with ChangeNotifier {
  QrScannerBackend _backend;

  ScannerProvider(this._backend);

  QrScannerBackend get backend => _backend;

  void switchToCodeScan() {
    _backend.dispose();
    _backend = CodeScanBackend();
    notifyListeners();
  }

  void switchToMobileScanner() {
    _backend.dispose();
    _backend = MobileScannerBackend();
    notifyListeners();
  }
}

// ----------------------------------------------------------------------
// 5️⃣  Haupt‑Widget (QR‑Scanner‑Screen)
// ----------------------------------------------------------------------
class QrScannerScreen extends StatefulWidget {
  const QrScannerScreen({Key? key}) : super(key: key);

  @override
  State<QrScannerScreen> createState() => _QrScannerScreenState();
}

class _QrScannerScreenState extends State<QrScannerScreen>
    with WidgetsBindingObserver, CameraHotReloadMixin {
  bool _processing = false;
  bool _torchOn = false;
  double _zoomFactor = 1.0;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    // Kamera beim ersten Frame starten
    SchedulerBinding.instance.addPostFrameCallback((_) {
      context.read<ScannerProvider>().backend.resumeCamera();
    });
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    // Wir delegieren das eigentliche Dispose an das Backend
    context.read<ScannerProvider>().backend.dispose();
    super.dispose();
  }

  // -----------------------------------------------------------------
  // 5️⃣1️⃣ App‑Lifecycle (Pause / Resume)
  // -----------------------------------------------------------------
  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (!mounted) return;
    final backend = context.read<ScannerProvider>().backend;
    if (state == AppLifecycleState.paused) {
      backend.pauseCamera();
    } else if (state == AppLifecycleState.resumed) {
      backend.resumeCamera();
    }
  }

  // -----------------------------------------------------------------
  // 5️⃣2️⃣ Orientation‑Change (didChangeMetrics)
  // -----------------------------------------------------------------
  @override
  void didChangeMetrics() {
    super.didChangeMetrics();
    // Wir warten bis das nächste Frame, weil MediaQuery erst dann aktualisiert ist
    SchedulerBinding.instance.addPostFrameCallback((_) {
      final orientation = MediaQuery.of(context).orientation;
      // Wir nutzen die Orientierung nur, um den Re‑Init‑Flow zu triggern.
      // Der eigentliche Re‑Init‑Code befindet sich in _handleOrientationChange().
      _handleOrientationChange(orientation);
    });
  }

  Orientation? _lastOrientation;

  Future<void> _handleOrientationChange(Orientation current) async {
    if (_lastOrientation == current) return; // nichts zu tun
    _lastOrientation = current;

    final backend = context.read<ScannerProvider>().backend;
    await backend.pauseCamera();
    await backend.dispose(); // alte Instanz freigeben

    // Neue Instanz erzeugen – wir nutzen das Provider‑Model dafür:
    // (hier wird einfach das gleiche Backend wieder gebaut; bei Switch
    //  zwischen CodeScan / MobileScanner würde man hier das gewünschte
    //  Backend auswählen.)
    final newBackend = backend is CodeScanBackend
        ? CodeScanBackend()
        : MobileScannerBackend();

    // Backend im Provider ersetzen
    context.read<ScannerProvider>()
      .._backend = newBackend; // wir greifen intern zu – das ist okay im Beispiel

    await newBackend.resumeCamera();
    if (mounted) setState(() {}); // UI neu bauen
  }

  // -----------------------------------------------------------------
  // 5️⃣3️⃣ Scan‑Callback
  // -----------------------------------------------------------------
  Future<void> _onDetect(String? code) async {
    if (code == null || _processing) return;

    _processing = true;
    final backend = context.read<ScannerProvider>().backend;
    await backend.pauseCamera(); // verhindert Doppel‑Scans

    try {
      // Hier ein Dummy‑Validierung – ersetze das durch deine Logik
      final bool isValid = await _fakeValidate(code);

      if (mounted && !isValid) {
        _processing = false;
        await backend.resumeCamera();
      } else {
        // Gültiger Code → du kannst z. B. zurücknavigieren
        if (mounted) Navigator.of(context).pop(code);
      }
    } catch (e) {
      // Fehler‑Dialog (einfacher SnackBar‑Fallback)
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Fehler beim Verarbeiten: $e')),
        );
        _processing = false;
        await backend.resumeCamera();
      }
    }
  }

  // Dummy‑Validator – ersetze das durch deine echte API‑Abfrage
  Future<bool> _fakeValidate(String code) async {
    await Future.delayed(const Duration(seconds: 1));
    // Beispiel: Nur Codes, die mit "OK" beginnen, gelten als gültig
    return code.startsWith('OK');
  }

  // -----------------------------------------------------------------
  // 5️⃣4️⃣ UI – Scaffold mit Torch‑ und Zoom‑Buttons
  // -----------------------------------------------------------------
  @override
  Widget build(BuildContext context) {
    final backend = context.watch<ScannerProvider>().backend;

    return Scaffold(
      appBar: AppBar(
        title: const Text('QR‑Scanner'),
        actions: [
          IconButton(
            icon: Icon(_torchOn ? Icons.flash_on : Icons.flash_off),
            onPressed: () async {
              _torchOn = !_torchOn;
              await backend.toggleTorch();
              setState(() {}); // Icon aktualisieren
            },
          ),
          PopupMenuButton<double>(
            icon: const Icon(Icons.zoom_out_map),
            onSelected: (factor) async {
              _zoomFactor = factor;
              await backend.setZoom(factor);
              setState(() {});
            },
            itemBuilder: (ctx) => [
              const PopupMenuItem(value: 1.0, child: Text('Zoom 1x')),
              const PopupMenuItem(value: 2.0, child: Text('Zoom 2x')),
              const PopupMenuItem(value: 3.0, child: Text('Zoom 3x')),
            ],
          ),
          PopupMenuButton<String>(
            icon: const Icon(Icons.swap_horiz),
            onSelected: (choice) {
              if (choice == 'code_scan') {
                context.read<ScannerProvider>().switchToCodeScan();
              } else {
                context.read<ScannerProvider>().switchToMobileScanner();
              }
            },
            itemBuilder: (_) => const [
              PopupMenuItem(value: 'code_scan', child: Text('code_scan')),
              PopupMenuItem(value: 'mobile_scanner', child: Text('mobile_scanner')),
            ],
          ),
        ],
      ),
      body: backend.buildView(
        viewKey: const Key('QR_VIEW'),
        onDetect: _onDetect,
        onAccessDenied: () async {
          // Simple Permission‑Dialog – ersetze durch deine UI‑Logik
          await showDialog(
            context: context,
            builder: (_) => AlertDialog(
              title: const Text('Kamera‑Zugriff verweigert'),
              content: const Text('Bitte erlaube den Kamerazugriff in den Einstellungen.'),
              actions: [
                TextButton(
                  onPressed: () => Navigator.of(context).pop(),
                  child: const Text('OK'),
                ),
              ],
            ),
          );
          return false; // verhindert automatisches Neustarten
        },
        onError: () {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(content: Text('Ein Fehler beim Lesen des QR‑Codes')),
          );
        },
      ),
    );
  }

  // -----------------------------------------------------------------
  // 5️⃣5️⃣ Hot‑Reload‑Hook (reassemble)
  // -----------------------------------------------------------------
  @override
  void reassemble() async {
    super.reassemble();
    if (!kDebugMode) return; // nur im Debug‑Modus relevant

    final backend = context.read<ScannerProvider>().backend;
    await backend.pauseCamera();
    await backend.dispose();

    // Neue Instanz – dieselbe Klasse wie vorher
    final freshBackend = backend is CodeScanBackend
        ? CodeScanBackend()
        : MobileScannerBackend();

    // Provider‑State aktualisieren
