mixin CameraHotReloadMixin<T extends StatefulWidget> on State<T> {
  Future<void> disposeCamera();

  Future<void> createAndStartCamera();

  @override
  void reassemble() async {
    super.reassemble();
    if (!kDebugMode) return;
    await disposeCamera();
    await createAndStartCamera();
    if (mounted) setState(() {});
  }
}

// ----------------------------------------------------------------------
