#ifndef GAMEMANAGER_H
#define GAMEMANAGER_H

#include <QObject>
#include <QVector>
#include "countrydata.h"

struct GuessResult {
    QString countryName;
    double distanceKm;
    QString direction; // e.g., "↗️ NE"
    int proximityPercent; // 0-100
};

class GameManager : public QObject {
    Q_OBJECT
public:
    explicit GameManager(QObject *parent = nullptr);

    void startNewGame();
    bool makeGuess(const QString& countryName);
    Country getTargetCountry() const { return m_targetCountry; }
    QVector<GuessResult> getGuessHistory() const { return m_guessHistory; }

signals:
    void guessAdded(const GuessResult& result);
    void gameWon();
    void gameLost();

private:
    double calculateDistance(double lat1, double lon1, double lat2, double lon2);
    QString calculateDirection(double lat1, double lon1, double lat2, double lon2);
    int calculateProximity(double distance);

    Country m_targetCountry;
    QVector<GuessResult> m_guessHistory;
    QHash<QString, Country> m_countries;
    const int MAX_ATTEMPTS = 6;
};

#endif // GAMEMANAGER_H
```

**gamemanager.cpp:**
```cpp
#include "gamemanager.h"
#include <QtMath>
#include <QRandomGenerator>

GameManager::GameManager(QObject *parent) : QObject(parent) {
    m_countries = getCountryDatabase();
}

void GameManager::startNewGame() {
    m_guessHistory.clear();
    auto values = m_countries.values();
    m_targetCountry = values[QRandomGenerator::global()->bounded(values.size())];
}

bool GameManager::makeGuess(const QString& countryName) {
    if (!m_countries.contains(countryName)) return false;

    const Country& guessed = m_countries[countryName];
    double dist = calculateDistance(guessed.latitude, guessed.longitude,
                                   m_targetCountry.latitude, m_targetCountry.longitude);

    GuessResult result;
    result.countryName = countryName;
    result.distanceKm = dist;
    result.direction = calculateDirection(guessed.latitude, guessed.longitude,
                                         m_targetCountry.latitude, m_targetCountry.longitude);
    result.proximityPercent = calculateProximity(dist);

    m_guessHistory.prepend(result);
    emit guessAdded(result);

    if (countryName == m_targetCountry.name) {
        emit gameWon();
        return true;
    }

    if (m_guessHistory.size() >= MAX_ATTEMPTS) {
        emit gameLost();
    }

    return false;
}

double GameManager::calculateDistance(double lat1, double lon1, double lat2, double lon2) {
    const double R = 6371.0; // Earth radius in km
    double lat1Rad = qDegreesToRadians(lat1);
    double lat2Rad = qDegreesToRadians(lat2);
    double deltaLat = qDegreesToRadians(lat2 - lat1);
    double deltaLon = qDegreesToRadians(lon2 - lon1);

    double a = qSin(deltaLat/2) * qSin(deltaLat/2) +
               qCos(lat1Rad) * qCos(lat2Rad) *
               qSin(deltaLon/2) * qSin(deltaLon/2);
    double c = 2 * qAtan2(qSqrt(a), qSqrt(1-a));
    return R * c;
}

QString GameManager::calculateDirection(double lat1, double lon1, double lat2, double lon2) {
    double dLon = qDegreesToRadians(lon2 - lon1);
    double lat1Rad = qDegreesToRadians(lat1);
    double lat2Rad = qDegreesToRadians(lat2);

    double y = qSin(dLon) * qCos(lat2Rad);
    double x = qCos(lat1Rad) * qSin(lat2Rad) - 
               qSin(lat1Rad) * qCos(lat2Rad) * qCos(dLon);
    double bearing = qRadiansToDegrees(qAtan2(y, x));
    bearing = fmod((bearing + 360.0), 360.0);

    // Convert to arrow direction
    if (bearing >= 337.5 || bearing < 22.5) return "↑ N";
    else if (bearing < 67.5) return "↗ NE";
    else if (bearing < 112.5) return "→ E";
    else if (bearing < 157.5) return "↘ SE";
    else if (bearing < 202.5) return "↓ S";
    else if (bearing < 247.5) return "↙ SW";
    else if (bearing < 292.5) return "← W";
    else return "↖ NW";
}

int GameManager::calculateProximity(double distance) {
    const double MAX_DISTANCE = 20000.0; // km
    return qMax(0, 100 - static_cast<int>((distance / MAX_DISTANCE) * 100));
}
