#include "countrymapwidget.h"
#include <QPainter>
#include <QPainterPath>

CountryMapWidget::CountryMapWidget(QWidget *parent) : QWidget(parent) {
    setMinimumSize(400, 300);
    setStyleSheet("background-color: #1a1a1a; border: 2px solid #3a3a3a; border-radius: 8px;");
}

void CountryMapWidget::setCountry(const Country& country) {
    projectCoordinates(country.outline);
    update();
}

void CountryMapWidget::projectCoordinates(const QVector<QPointF>& coords) {
    m_polygon.clear();
    // Simple equirectangular projection
    for (const auto& coord : coords) {
        double x = (coord.x() + 10) * 20; // lon + offset * scale
        double y = (60 - coord.y()) * 8;  // 60 - lat * scale
        m_polygon << QPointF(x, y);
    }
}

void CountryMapWidget::paintEvent(QPaintEvent* event) {
    Q_UNUSED(event)
    QPainter painter(this);
    painter.setRenderHint(QPainter::Antialiasing);

    // Center and scale polygon
    QRectF bounds = m_polygon.boundingRect();
    if (bounds.isEmpty()) return;

    double scale = qMin(width() / bounds.width(), height() / bounds.height()) * 0.8;
    QPolygonF scaled = m_polygon;

    for (QPointF& pt : scaled) {
        pt = pt * scale;
        pt += QPointF(width()/2 - bounds.center().x() * scale,
                      height()/2 - bounds.center().y() * scale);
    }

    // Draw country shape
    QPainterPath path;
    path.addPolygon(scaled);
    painter.fillPath(path, QColor("#4CAF50"));
    painter.setPen(QPen(QColor("#81C784"), 2));
    painter.drawPath(path);
}
