void MainWindow::setupUI() {
    auto* centralWidget = new QWidget(this);
    setCentralWidget(centralWidget);

    auto* mainLayout = new QHBoxLayout(centralWidget);

    // Left panel - Map
    auto* leftPanel = new QVBoxLayout();
    m_mapWidget = new CountryMapWidget(this);
    leftPanel->addWidget(m_mapWidget);

    m_attemptsLabel = new QLabel("Attempts: 0/6", this);
    m_attemptsLabel->setStyleSheet("font-size: 16px; font-weight: bold;");
