    mainLayout->addLayout(leftPanel);

    // Right panel - Guesses
    auto* rightPanel = new QVBoxLayout();

    auto* inputLayout = new QHBoxLayout();
    m_guessInput = new QLineEdit(this);
    m_guessInput->setPlaceholderText("Enter country name...");

    // Set up autocomplete
    QStringList countryNames;
    auto countries = getCountryDatabase();
    for (const auto& country : countries) {
        countryNames << country.name;
    }
    QCompleter* completer = new QCompleter(countryNames, this);
    completer->setCaseSensitivity(Qt::CaseInsensitive);
    m_guessInput->setCompleter(completer);

    m_submitButton = new QPushButton("Guess", this);
    inputLayout->addWidget(m_guessInput);
    inputLayout->addWidget(m_submitButton);

    rightPanel->addLayout(inputLayout);

    m_guessList = new QListWidget(this);
    m_guessList->setStyleSheet(R"(
