void MainWindow::onGuessSubmitted() {
    QString guess = m_guessInput->text().trimmed();
    if (guess.isEmpty()) return;

    m_gameManager->makeGuess(guess);
    m_guessInput->clear();
}

void MainWindow::onGuessAdded(const GuessResult& result) {
    updateGuessDisplay(result);
    m_attemptsLabel->setText(QString("Attempts: %1/6").arg(m_gameManager->getGuessHistory().size()));
}

void MainWindow::updateGuessDisplay(const GuessResult& result) {
    QString text = QString("<b>%1</b><br>"
                          "Distance: %2 km<br>"
                          "Direction: %3<br>"
                          "Proximity: %4%")
            .arg(result.countryName)
            .arg(static_cast<int>(result.distanceKm))
            .arg(result.direction)
            .arg(result.proximityPercent);

    auto* item = new QListWidgetItem(text);

    // Color based on proximity
    if (result.proximityPercent > 80) {
        item->setBackground(QColor("#4CAF50"));
    } else if (result.proximityPercent > 50) {
        item->setBackground(QColor("#FFC107"));
    } else {
        item->setBackground(QColor("#F44336"));
    }
    item->setForeground(Qt::white);

    m_guessList->insertItem(0, item);
}

void MainWindow::onGameWon() {
    QMessageBox::information(this, "Congratulations!", 
                           QString("You found %1!").arg(m_gameManager->getTargetCountry().name));
    m_gameManager->startNewGame();
    m_mapWidget->setCountry(m_gameManager->getTargetCountry());
    m_guessList->clear();
}

void MainWindow::onGameLost() {
