def longest_palindromic_no_vowel(s: str) -> int:
    vowels = set('aeiouAEIOU')
    max_len = 0
    n = len(s)
    for i in range(n):
        if s[i] in vowels:
            continue
        cur = []
        for j in range(i, n):
